def algorithm(func, dim, lb, ub, budget, rng):
    x_best = -np.inf * np.ones(dim)
    for i in range(budget):
        step_size = 5.0 / (i + 1) ** 0.6
        candidate = lb + (ub - lb) * rng.uniform(size=dim)
        new_candidate = clip(candidate, lb, ub)
        f_new_candidate = func(new_candidate)
        if f_new_candidate < func(x_best):
            x_best = new_candidate
    return x_best
